import numpy as np

class PrioritizedBuffer:
    def __init__(self, capacity, alpha=0.6, eps=1e-6):
        self.data = []
        self.prio = np.zeros(capacity, dtype=np.float64)
        self.capacity, self.alpha, self.eps = capacity, alpha, eps
        self.pos = 0

    def add(self, transition):
        # new transitions get MAX priority so every one is replayed at least once;
        # initialising them at zero means a transition can never be sampled and so
        # never gets a priority - it is invisible forever
        self.prio[self.pos] = self.prio.max() if self.data else 1.0
        if len(self.data) < self.capacity:
            self.data.append(transition)
        else:
            self.data[self.pos] = transition
        self.pos = (self.pos + 1) % self.capacity

    def sample(self, batch, beta=0.4):
        p = self.prio[:len(self.data)] ** self.alpha
        p = p / p.sum()
        idx = np.random.choice(len(self.data), batch, p=p)
        w = (len(self.data) * p[idx]) ** (-beta)
        return idx, [self.data[i] for i in idx], w / w.max()

    def update(self, idx, td_errors):
        self.prio[idx] = np.abs(td_errors) + self.eps    # eps: never priority zero
